import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Tenant API v1 — Payments","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Payments | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-payments"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Payments | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-payments"}]]},"headers":[],"relativePath":"api/tenant-v1-payments.md","filePath":"api/tenant-v1-payments.md","lastUpdated":1787485542000}'),n={name:"api/tenant-v1-payments.md"};function d(i,e,c,r,p,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="tenant-api-v1-—-payments" tabindex="-1">Tenant API v1 — Payments <a class="header-anchor" href="#tenant-api-v1-—-payments" aria-label="Permalink to &quot;Tenant API v1 — Payments&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:payments</code>, plus permission middleware / policies.</p><blockquote><p><strong>Naming:</strong> the model is <code>CustomerPayment</code> — a payment a tenant <em>receives from its own customer</em>, allocated against that customer&#39;s <code>CustomerInvoice</code>(s). Central&#39;s own platform-billing Payments ledger (subscription payments tenants make to the platform) is unrelated.</p></blockquote><p>Requires the <strong>Invoices</strong> module (hard <code>module_dependencies</code> row) — allocations reference <code>CustomerInvoice</code> rows and cannot be created without it.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-payments-stats" tabindex="-1">GET <code>/payments/stats</code> <a class="header-anchor" href="#get-payments-stats" aria-label="Permalink to &quot;GET `/payments/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_payments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_payments&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;posted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;void&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;posted_amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>posted_amount</code> sums <code>amount</code> across payments with <code>status = posted</code>.</p><h2 id="payments-crud" tabindex="-1">Payments CRUD <a class="header-anchor" href="#payments-crud" aria-label="Permalink to &quot;Payments CRUD&quot;">​</a></h2><h3 id="get-payments" tabindex="-1">GET <code>/payments</code> <a class="header-anchor" href="#get-payments" aria-label="Permalink to &quot;GET `/payments`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>number</code> or <code>reference</code>), <code>status</code> (<code>draft</code>|<code>posted</code>|<code>void</code>), <code>method</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_payments</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>amount</code>, <code>currency</code>, <code>method</code>, <code>paid_at</code>, <code>reference</code>, <code>notes</code>, <code>contact</code>/<code>company</code> refs, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-payments" tabindex="-1">POST <code>/payments</code> <a class="header-anchor" href="#post-payments" aria-label="Permalink to &quot;POST `/payments`&quot;">​</a></h3><p>Body: <code>amount</code> (required, numeric, min <code>0.01</code>), <code>currency</code> (3-letter, optional), <code>method</code> (required — <code>cash</code>|<code>bank_transfer</code>|<code>cheque</code>|<code>card_manual</code>|<code>other</code>), <code>paid_at</code> (optional date), <code>reference</code>, <code>notes</code>, <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated via <code>LinkableContact</code>/<code>LinkableCompany</code>), <code>assigned_to</code>, <code>deposit_account_id</code> (optional — active cash/bank account when Accounting is entitled; ignored otherwise), <code>allocations</code> (optional array of <code>{ customer_invoice_id, amount }</code>).</p><p>Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>PAY-00001</code>, configurable via the <code>payments_number_prefix</code> tenant setting). <code>number</code> is unique per tenant at the database level; on the rare concurrent-create collision, the service retries with a freshly generated number (up to 3 attempts). Allocations are stored on the draft but <strong>not</strong> applied to any invoice balance until the payment is posted — so allocation amounts are <strong>not</strong> validated against the invoice&#39;s balance due at create/update time, only at post time (see below).</p><h3 id="get-payments-id" tabindex="-1">GET <code>/payments/{id}</code> <a class="header-anchor" href="#get-payments-id" aria-label="Permalink to &quot;GET `/payments/{id}`&quot;">​</a></h3><p>Includes contact, company, assignee, creator, allocations (each with its <code>customer_invoice</code> ref: <code>number</code>/<code>total</code>/<code>balance_due</code>/<code>status</code>), notes, and timeline activities. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="put-payments-id" tabindex="-1">PUT <code>/payments/{id}</code> <a class="header-anchor" href="#put-payments-id" aria-label="Permalink to &quot;PUT `/payments/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> payments only — including replacing the full <code>allocations</code> set. Non-draft payments return 422 on <code>status</code> (<code>Only draft payments can be edited.</code>). Assignment after posting uses <code>POST /payments/{id}/assign</code>.</p><h3 id="delete-payments-id" tabindex="-1">DELETE <code>/payments/{id}</code> <a class="header-anchor" href="#delete-payments-id" aria-label="Permalink to &quot;DELETE `/payments/{id}`&quot;">​</a></h3><p>Soft delete. <strong>Draft only</strong> — same 422 guard as update. Permission: <code>payments.delete</code>.</p><h3 id="post-payments-id-restore" tabindex="-1">POST <code>/payments/{id}/restore</code> <a class="header-anchor" href="#post-payments-id-restore" aria-label="Permalink to &quot;POST `/payments/{id}/restore`&quot;">​</a></h3><p>Permission: <code>payments.restore</code>.</p><h3 id="delete-payments-id-force" tabindex="-1">DELETE <code>/payments/{id}/force</code> <a class="header-anchor" href="#delete-payments-id-force" aria-label="Permalink to &quot;DELETE `/payments/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted payment. Permission: <code>payments.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-payments-id-assign" tabindex="-1">POST <code>/payments/{id}/assign</code> <a class="header-anchor" href="#post-payments-id-assign" aria-label="Permalink to &quot;POST `/payments/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>payments.assign</code>.</p><h3 id="post-payments-id-post" tabindex="-1">POST <code>/payments/{id}/post</code> <a class="header-anchor" href="#post-payments-id-post" aria-label="Permalink to &quot;POST `/payments/{id}/post`&quot;">​</a></h3><p>Transitions <code>draft → posted</code>. Every allocation&#39;s invoice is locked (<code>SELECT ... FOR UPDATE</code>) and validated <strong>before</strong> any amount is applied — a payment either posts in full or rejects with no partial effect. An allocation is rejected with a 422 on <code>allocations</code> (naming the invoice number) when:</p><ul><li>the invoice cannot be found — deliberately <strong>not</strong> <code>withTrashed()</code>, so a soft-deleted invoice can never receive a payment;</li><li>the invoice&#39;s status is not <code>sent</code> or <code>partial</code>;</li><li>the allocation amount exceeds the invoice&#39;s current <code>balance_due</code> (0.01 tolerance for float rounding); or</li><li>the payment and invoice both have a <code>currency</code> set and they don&#39;t match.</li></ul><p>Once every allocation passes, each adds <code>amount</code> to its invoice&#39;s <code>amount_paid</code> and calls <code>CustomerInvoice::recalculateBalanceFromAmounts()</code>, which recomputes <code>balance_due</code> and advances the invoice status. Permission: <code>payments.post</code>. Rejects with 422 on <code>status</code> if the payment isn&#39;t currently <code>draft</code>.</p><p>When <strong>Accounting</strong> is entitled: allocations must sum to the payment amount (0.01 tolerance); a posted journal is created (<strong>Dr</strong> <code>deposit_account_id</code> or system Cash <code>1000</code> / <strong>Cr</strong> AR <code>1100</code>) and linked via <code>journal_entry_id</code>.</p><h3 id="post-payments-id-void" tabindex="-1">POST <code>/payments/{id}/void</code> <a class="header-anchor" href="#post-payments-id-void" aria-label="Permalink to &quot;POST `/payments/{id}/void`&quot;">​</a></h3><p>Transitions <code>posted → void</code>. Reverses each allocation&#39;s amount from its invoice&#39;s <code>amount_paid</code> and recalculates the invoice balance/status. Unlike <code>post()</code>, this locks the invoice <strong>with</strong> <code>withTrashed()</code> and does not re-check its status — voiding a payment is a ledger correction that must succeed even if the invoice has since been fully paid, moved past open statuses, or soft-deleted, otherwise the invoice&#39;s <code>amount_paid</code> would permanently disagree with the payment record. When Accounting posted a journal for this payment, that journal is <strong>voided</strong>. Permission: <code>payments.void</code>. Rejects with 422 on <code>status</code> if the payment isn&#39;t currently <code>posted</code>.</p><h3 id="post-payments-id-notes" tabindex="-1">POST <code>/payments/{id}/notes</code> <a class="header-anchor" href="#post-payments-id-notes" aria-label="Permalink to &quot;POST `/payments/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>payments.update</code>.</p><h3 id="get-payments-id-timeline" tabindex="-1">GET <code>/payments/{id}/timeline</code> <a class="header-anchor" href="#get-payments-id-timeline" aria-label="Permalink to &quot;GET `/payments/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>posted</code>, <code>voided</code>, <code>note_added</code>, <code>emailed</code>, <code>deleted</code>, <code>restored</code>).</p><h3 id="get-payments-id-pdf" tabindex="-1">GET <code>/payments/{id}/pdf</code> <a class="header-anchor" href="#get-payments-id-pdf" aria-label="Permalink to &quot;GET `/payments/{id}/pdf`&quot;">​</a></h3><p>Download a branded <strong>receipt PDF</strong> for a <strong>posted</strong> payment. Throttled (<code>payments-pdf</code>). Draft or void payments return 422. Permission: <code>payments.view</code>.</p><h3 id="post-payments-id-email" tabindex="-1">POST <code>/payments/{id}/email</code> <a class="header-anchor" href="#post-payments-id-email" aria-label="Permalink to &quot;POST `/payments/{id}/email`&quot;">​</a></h3><p>Email the receipt to the customer with optional PDF attachment. Body matches billing document email (<code>to</code>, <code>cc</code>, <code>subject</code>, <code>message</code>, <code>attach_pdf</code>). Permission: <code>payments.send</code>. Throttled (<code>billing-document-email</code>). <strong>Posted</strong> only — draft/void → 422. Default <code>to</code> resolves from linked contact/company email (<code>ResolvesBillingDocumentRecipients</code>). Records <code>emailed</code> on the domain timeline.</p>',47)])])}const u=t(n,[["render",d]]);export{h as __pageData,u as default};
